ckh_key_t *key_copy;
ckh_data_t *data_copy;
unsigned hash1, hash2;
ckh_key_t *aux_key;
ckh_data_t *aux_data;
unsigned ninserts = 0;
unsigned i;

ckh->nitems++;
if (ckh->nitems > ckh->ngrow) {
    ckh->nitems--;
    return true;
}

key_copy = (ckh_key_t *)key;
data_copy = (ckh_data_t *)data;
hash1 = ckh->hash(key_copy);
hash2 = ckh->hash2(key_copy);

while (ninserts < 2 * ckh->nslots) {
    unsigned hash = (ninserts < ckh->nslots) ? hash1 : hash2;
    i = hash % ckh->nslots;

    if (ckh->has_key(i) == false) {
        ckh->key_put(i, key_copy);
        ckh->data_put(i, data_copy);
        return false;
    } else {
        aux_key = ckh->key_get(i);
        aux_data = ckh->data_get(i);
        ckh->key_put(i, key_copy);
        ckh->data_put(i, data_copy);
        key_copy = aux_key;
        data_copy = aux_data;
        hash1 = ckh->hash(key_copy);
        hash2 = ckh->hash2(key_copy);
        ninserts++;
    }
}

ckh->nitems--;
return true;
// END_CODE

